import sys
from collections import deque, defaultdict

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1

    adj = [[] for _ in range(N)]
    for _ in range(M):
        x = int(data[idx]) - 1; idx += 1
        y = int(data[idx]) - 1; idx += 1
        z = int(data[idx]); idx += 1
        adj[x].append((y, z))
        adj[y].append((x, z))

    parent = list(range(N))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for i in range(N):
        for (j, _) in adj[i]:
            union(i, j)

    components = defaultdict(list)
    for i in range(N):
        components[find(i)].append(i)

    c = [-1] * N
    A = [0] * N

    for comp_nodes in components.values():
        root = comp_nodes[0]
        c[root] = 0
        queue = deque([root])

        while queue:
            u = queue.popleft()
            cu = c[u]
            for (v, z) in adj[u]:
                if c[v] == -1:
                    c[v] = cu ^ z
                    queue.append(v)
                elif (cu ^ c[v]) != z:
                    print(-1)
                    return

        size = len(comp_nodes)
        bit_counts = [0] * 31
        for node in comp_nodes:
            val = c[node]
            for b in range(31):
                if (val >> b) & 1:
                    bit_counts[b] += 1

        x_val = 0
        for b in range(31):
            if bit_counts[b] > size - bit_counts[b]:
                x_val |= (1 << b)

        for node in comp_nodes:
            A[node] = x_val ^ c[node]

    sys.stdout.write(' '.join(map(str, A)) + '\n')

main()

import sys
import math

def icbrt(n):
    """floor of cube root of n (n >= 1)."""
    lo, hi = 1, 1
    while hi * hi * hi <= n:
        hi <<= 1
    while lo < hi:
        mid = (lo + hi + 1) >> 1
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])

    # Any solution satisfies d = x - y divides N and d < cbrt(N).
    lim = icbrt(N)
    for d in range(1, lim + 1):
        if N % d != 0:
            continue
        m = N // d                      # m = x^2 + x*y + y^2 = 3y^2 + 3dy + d^2
        disc = 12 * m - 3 * d * d       # discriminant of the quadratic in y
        if disc <= 0:
            continue
        s = math.isqrt(disc)
        if s * s != disc:
            continue
        num = s - 3 * d                 # numerator must be positive and divisible by 6
        if num <= 0 or num % 6 != 0:
            continue
        y = num // 6
        x = y + d
        if x <= 0 or y <= 0:
            continue
        # Final verification
        if x * x * x - y * y * y == N:
            sys.stdout.write(f"{x} {y}\n")
            return
    sys.stdout.write("-1\n")

if __name__ == "__main__":
    solve()

